def min_swaps(data):
    k = sum(data)
    if k == 0 or k == len(data):
        return 0
    best = float('inf')
    for i in range(len(data) - k + 1):
        zeros = sum(1 for x in data[i:i + k] if x == 0)   # recount every single window
        best = min(best, zeros)
    return best

