    static int minSwaps(int[] data) {
        int n = data.length, k = 0;
        for (int x : data) k += x;
        if (k == 0 || k == n) return 0;
        int best = Integer.MAX_VALUE;
        for (int i = 0; i + k <= n; i++) {
            int zeros = 0;
            for (int j = i; j < i + k; j++) if (data[j] == 0) zeros++;  // recount every single window
            best = Math.min(best, zeros);
        }
        return best;
    }
}

