def min_swaps(data):
    n = len(data)
    k = sum(data)
    if k == 0 or k == n:
        return 0
    zeros = data[:k].count(0)          # first window, counted once
    best = zeros
    for i in range(k, n):
        if data[i] == 0:
            zeros += 1                   # entering element
        if data[i - k] == 0:
            zeros -= 1                   # leaving element
        best = min(best, zeros)
    return best

